import{_ as r,c as i,o as t,a2 as l}from"./chunks/framework.PGES7OoM.js";const h=JSON.parse(`{"title":"Building blocks","description":"","frontmatter":{"rawMarkdown":"# Building blocks\\n\\nThe core building blocks of the Curvy privacy protocol are:\\n\\n- [Curvy ID](./curvy-id)\\n  - Stores users' public keys associated with their Curvy ID\\n  - Executes ENS resolves\\n\\n- [Portals](./portals)\\n  - Automates shielding to solve the problem of [time locality](/for-the-curious/privacy-model#time-locality)\\n  - Delivers the best possible UX to senders, regardless of their wallet choice.\\n\\n- [Privacy Aggregator](./privacy-aggregator)\\n  - Shields users funds by offering complete opaqueness of the sender, recipient, amount and currency in private transfers\\n  - Utilizes ZK proofs and Merkle trees\\n\\n- [Curvy SDK](./curvy-sdk)\\n  - Open-source client-side TypeScript package that provides the [complete set of Curvy features](/for-users/index)\\n  - \\"Glues\\" all components together by orchestrating and facilitating users' intents\\n","rawMarkdownPath":"/_raw/for-the-curious/building-blocks/index.md","rawMarkdownTitle":"Building blocks","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-the-curious/building-blocks/index.md"},"headers":[],"relativePath":"for-the-curious/building-blocks/index.md","filePath":"for-the-curious/building-blocks/index.md","lastUpdated":1784144016000}`),s={name:"for-the-curious/building-blocks/index.md"};function o(a,e,n,c,u,d){return t(),i("div",null,[...e[0]||(e[0]=[l("",3)])])}const f=r(s,[["render",o]]);export{h as __pageData,f as default};
